import{_ as s,o as t,c as r,a3 as n}from"./chunks/framework.BlfGB29P.js";const i="/eep/ini-edit-translate-2026/editor-v2-1-37-fr.png",a="/eep/ini-edit-translate-2026/info-trans-v2-1-37-fr.png",o="/eep/ini-edit-translate-2026/dictionary-v2-1-37-fr.png",h=JSON.parse('{"title":"INI Edit Translate 2026","description":"Fonctions de l’éditeur Windows de fichiers INI de modèles EEP et d’Installation.eep avec traduction ChatGPT.","frontmatter":{"title":"INI Edit Translate 2026","description":"Fonctions de l’éditeur Windows de fichiers INI de modèles EEP et d’Installation.eep avec traduction ChatGPT."},"headers":[],"relativePath":"fr/eep/ini-edit-translate-2026/index.md","filePath":"fr/eep/ini-edit-translate-2026/index.md","lastUpdated":1792852622000}'),l={name:"fr/eep/ini-edit-translate-2026/index.md"};function d(c,e,u,p,m,f){return t(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="ini-edit-translate-2026" tabindex="-1">INI Edit Translate 2026 <a class="header-anchor" href="#ini-edit-translate-2026" aria-label="Permalink to &quot;INI Edit Translate 2026&quot;">​</a></h1><h2 id="version-2-1-51-message-lors-de-la-selection-d-un-dossier" tabindex="-1">Version 2.1.51 : message lors de la sélection d’un dossier <a class="header-anchor" href="#version-2-1-51-message-lors-de-la-selection-d-un-dossier" aria-label="Permalink to &quot;Version 2.1.51 : message lors de la sélection d’un dossier&quot;">​</a></h2><p>Sélectionner un dossier dans l’arborescence affiche <strong>« Veuillez sélectionner un fichier INI. »</strong> Les textes, tableaux, aperçu et fichier sélectionné sont conservés. Un dossier n’est plus lu comme un fichier et aucune traduction n’est lancée.</p><p>Cela concerne le dossier racine et les sous-dossiers de tout nom, y compris ceux portant une extension <code>.ini</code>. Les fichiers disparus et autres types de fichiers affichent le même message. Seul un fichier INI existant est ouvert ; <code>.INI</code> en majuscules est également reconnu. Le nœud sélectionné remplace la position du pointeur, y compris pour la navigation au clavier. Message disponible en allemand, anglais et français.</p><p>101 vérifications locales réussies, dont conservation des données lors de la sélection d’un dossier dans les trois langues et ouverture d’un INI sans dépendre du pointeur. Sauvegarde effectuée ; données personnelles et identifiants conservés.</p><h2 id="version-2-1-50-proteger-les-controles-eep-identifiants-et-versions" tabindex="-1">Version 2.1.50 : protéger les contrôles EEP, identifiants et versions <a class="header-anchor" href="#version-2-1-50-proteger-les-controles-eep-identifiants-et-versions" aria-label="Permalink to &quot;Version 2.1.50 : protéger les contrôles EEP, identifiants et versions&quot;">​</a></h2><p><code>[e]</code> reste un code de saut de ligne EEP : il n’est ni traduit ni remplacé par un vrai saut de ligne. L’écriture exacte, le nombre et l’ordre des marqueurs protégés sont vérifiés.</p><p>Les identifiants de constructeurs sont reconnus par des motifs lettres/chiffres, sans liste de noms fixe : <code>(GK3)</code>, <code>(AG3)</code>, <code>(DL1)</code>, mais aussi les anciens codes sans parenthèses au début, au milieu ou à la fin. Aucun code n’est ajouté s’il est absent. Les ajouts ordinaires tels que <code>(Winter)</code> restent traduisibles. Sans liste supplémentaire, les codes particuliers composés uniquement de lettres ne peuvent pas être distingués de façon fiable des mots ordinaires.</p><p>Les versions comme <code>EEP16.2</code>, <code>eep16.2</code> et <code>EEP 16.2</code> gardent leur casse et ponctuation. MyMemory ne reçoit pas les segments protégés ; les codes ou contrôles modifiés ou inventés par OpenAI/ChatGPT sont rejetés. La protection par restauration reste active.</p><p>Une entrée de configuration ajoutée en 2.1.49 pouvait empêcher le démarrage. Elle est corrigée et la configuration distribuée est désormais vérifiée. <strong>Si 2.1.49 ne démarre plus :</strong> sauvegarder <code>INI Edit Translate 2026.exe.config</code>, télécharger le fichier de configuration supplémentaire de la version 2.1.50, le renommer <code>INI Edit Translate 2026.exe.config</code> et remplacer celui situé à côté de l’EXE. Démarrer puis installer normalement la mise à jour 2.1.50. Ne pas remplacer les fichiers INI, bases de données ou paramètres personnels.</p><p>99 vérifications locales réussies. Un test d’installation avec code initial, version, code entre parenthèses et deux contrôles <code>[e]</code> a réellement été traduit via MyMemory, enregistré et relu. Fichiers originaux et identifiants conservés.</p><h2 id="version-2-1-49-conserver-le-dernier-dossier" tabindex="-1">Version 2.1.49 : conserver le dernier dossier <a class="header-anchor" href="#version-2-1-49-conserver-le-dernier-dossier" aria-label="Permalink to &quot;Version 2.1.49 : conserver le dernier dossier&quot;">​</a></h2><p>Activer <strong>Conserver le dernier dossier</strong> dans <strong>À propos → Paramètres</strong>, puis <strong>Enregistrer</strong>. Le dernier dossier choisi est conservé après redémarrage et mise à jour. L’arborescence et les sélecteurs de fichiers INI / Installation.eep repartent de ce dossier. Aucun fichier n’est ouvert ni traduit automatiquement.</p><p>L’option est désactivée par défaut. Si un dossier ou lecteur réseau est indisponible, un message apparaît et le chemin est conservé pour le prochain démarrage. Les données et identifiants existants sont conservés. 94 vérifications locales réussies, dont enregistrement/relecture, désactivation, dossier indisponible et affichage DE/EN/FR aux échelles 100/150 %.</p><p><strong>Version 2.1.51.0 · Windows 11 · .NET Framework 4.8</strong></p><p>Modifier les descriptions de modèles EEP et leurs fichiers d’installation. Développé par Uwe Grimm / UGSo Software et publié sous licence MIT.</p><p><a href="https://github.com/rockbaer2007/ini-edit-translate-2026" target="_blank" rel="noreferrer">Code source et README sur GitHub</a></p><p><img src="'+i+'" alt="Interface de la version 2.1.37 avec barre de menus Lime, sans données personnelles"></p><h2 id="version-2-1-48-retablir-la-traduction-des-noms-de-sous-ensembles" tabindex="-1">Version 2.1.48 : rétablir la traduction des noms de sous-ensembles <a class="header-anchor" href="#version-2-1-48-retablir-la-traduction-des-noms-de-sous-ensembles" aria-label="Permalink to &quot;Version 2.1.48 : rétablir la traduction des noms de sous-ensembles&quot;">​</a></h2><p>Les noms et descriptions des cinq sous-ensembles <code>Install_00</code> à <code>Install_04</code> sont de nouveau traduits. Seuls les noms de modèles dans la section des modèles restent protégés. Les textes sources sont conservés ; l’allemand et le français utilisent toujours l’anglais comme langue intermédiaire.</p><p>Les cinq boutons et l’importation automatique utilisent la même correspondance vérifiée des champs. Le bouton du deuxième sous-ensemble traite désormais ses propres champs. Les résultats ne sont appliqués qu’après traduction complète ; une erreur ou une annulation conserve les noms et descriptions du sous-ensemble.</p><p>91 vérifications locales réussies. Un sous-ensemble de test nommé « Detailmodell Großdiesellokomotive V140 001 DRG » a réellement été traduit via MyMemory, enregistré et relu ; les noms de modèles et un champ INI supplémentaire ont été conservés. Le fichier de l’ordinateur de jeu distant n’a pas été modifié.</p><h2 id="telechargement" tabindex="-1">Téléchargement <a class="header-anchor" href="#telechargement" aria-label="Permalink to &quot;Téléchargement&quot;">​</a></h2><p><a href="https://github.com/rockbaer2007/ini-edit-translate-2026/releases/download/v2.1.51/INI-Edit-Translate-2026-v2.1.51-windows.zip" target="_blank" rel="noreferrer">Télécharger le ZIP Windows v2.1.51</a> · <a href="https://github.com/rockbaer2007/ini-edit-translate-2026/releases/tag/v2.1.51" target="_blank" rel="noreferrer">Version GitHub et SHA-256</a></p><p>Extraire tout le ZIP et lancer <code>INI Edit Translate 2026.exe</code>. Windows 11 et .NET Framework 4.8 sont requis. Conserver les DLL et dossiers de langues ensemble. Visual Studio sert uniquement à compiler les sources. Aucun installateur nécessaire.</p><h2 id="fonctions" tabindex="-1">Fonctions <a class="header-anchor" href="#fonctions" aria-label="Permalink to &quot;Fonctions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Domaine</th><th>Possibilités</th></tr></thead><tbody><tr><td>Textes de modèles</td><td>Modifier les noms et descriptions en EN/DE/FR/PL</td></tr><tr><td>Métadonnées</td><td>Modifier les références PDF, génération, années d’utilisation, pays et icône</td></tr><tr><td>Axes de mouvement et fonctions des signaux</td><td>Afficher, modifier et traduire les entrées par langue</td></tr><tr><td>Installation.eep</td><td>Modifier les noms et descriptions des sections d’installation prises en charge</td></tr><tr><td>Aperçu</td><td>Comparer le fichier original à l’aperçu du résultat</td></tr><tr><td>Export des tableaux</td><td>Export complet en UTF-8 avec BOM et séparateurs de tabulation</td></tr><tr><td>Sauvegardes</td><td>Copier les fichiers INI existants avant remplacement, en conservant leur nom d’origine</td></tr></tbody></table><h2 id="fournisseurs-de-traduction" tabindex="-1">Fournisseurs de traduction <a class="header-anchor" href="#fournisseurs-de-traduction" aria-label="Permalink to &quot;Fournisseurs de traduction&quot;">​</a></h2><p>Dans <strong>Options → Paramètres de traduction</strong>, choisir API OpenAI, abonnement ChatGPT ou <strong>MyMemory</strong>. MyMemory nécessite Internet, mais aucune clé ni aucun compte. Une adresse e-mail facultative est envoyée avec chaque requête : selon le fournisseur, 5 000 caractères par jour sans identification, jusqu’à 50 000 avec une adresse valide. Chaque langue cible compte séparément. Les textes longs sont découpés en segments de 500 octets UTF-8 maximum. Un cache temporaire évite les répétitions pendant une opération.</p><p>L’allemand est la langue par défaut. La langue choisie pour l’interface définit la langue source initiale ; les axes/fonctions des signaux gardent leur sélecteur de source. L’allemand et le français sont d’abord traduits en anglais ; les autres langues cibles utilisent ce texte intermédiaire anglais. Cela vaut pour tous les fournisseurs. Le texte source choisi et les noms de modèles sont conservés.</p><p>MyMemory peut conserver durablement les textes transmis. L’application utilise uniquement la requête de traduction et ne publie pas d’entrées supplémentaires dans un dictionnaire. Aucun changement automatique de fournisseur. Les clés API, connexions ChatGPT, modèles et dictionnaires existants sont conservés. L’enregistrement INI préserve les caractères polonais grâce à Unicode ; si nécessaire, le fichier de sortie sauvegardé est enregistré en UTF-16 avec BOM. Le traitement réel de cet encodage dans EEP n’a pas été testé ici.</p><p>90 vérifications locales ont réussi. Le fichier INI fourni a été ouvert, traduit par de véritables appels MyMemory et enregistré dans une copie ; l’original reste inchangé. Relire les traductions automatiques des termes techniques avant utilisation.</p><p><a href="https://mymemory.translated.net/doc/spec.php" target="_blank" rel="noreferrer">API MyMemory</a> · <a href="https://mymemory.translated.net/doc/usagelimits.php" target="_blank" rel="noreferrer">Quotas</a> · <a href="https://mymemory.translated.net/terms-and-conditions" target="_blank" rel="noreferrer">Utilisation des données</a></p><h2 id="installation-et-utilisation" tabindex="-1">Installation et utilisation <a class="header-anchor" href="#installation-et-utilisation" aria-label="Permalink to &quot;Installation et utilisation&quot;">​</a></h2><ol><li>Télécharger le ZIP Windows ci-dessus et extraire tous les fichiers.</li><li>Lancer <code>INI Edit Translate 2026.exe</code> depuis le dossier extrait en conservant ses DLL et dossiers de langues.</li><li>Ouvrir <strong>À propos → Paramètres → Paramètres de traduction</strong>. Choisir MyMemory, API OpenAI ou abonnement ChatGPT. MyMemory ne nécessite pas de connexion ; l’e-mail est facultatif.</li><li>Ouvrir d’abord une copie sauvegardée en mode <strong>Lecture seule</strong>.</li><li>Utiliser <strong>Lire et traduire</strong> ou un bouton de traduction. Choisir la langue source des axes et fonctions des signaux.</li><li>Vérifier l’aperçu et les textes, puis enregistrer explicitement.</li></ol><p>La fenêtre d’information choisit l’aide révisée <code>Info.de.rtf</code>, <code>Info.en.rtf</code> ou <code>Info.fr.rtf</code> selon la langue de l’interface. Le fichier historique <code>Info.rtf</code> est conservé sans modification. L’aide actuelle décrit OpenAI et le programme de référence restauré.</p><h2 id="mises-a-jour-github" tabindex="-1">Mises à jour GitHub <a class="header-anchor" href="#mises-a-jour-github" aria-label="Permalink to &quot;Mises à jour GitHub&quot;">​</a></h2><p>Choisir <strong>À propos → Rechercher des mises à jour</strong> pour consulter la dernière version publique sur GitHub. Aucune vérification automatique au démarrage. Seule une version stable plus récente est proposée, avec son numéro et ses notes de publication.</p><p><strong>Télécharger et installer</strong> récupère le ZIP Windows et sa somme SHA-256. Le téléchargement et la vérification peuvent être annulés avant la fermeture du programme. Enregistrer les fichiers ouverts et fermer Info_trans avant l’installation, puis confirmer. Un programme auxiliaire attend la fermeture de l’éditeur, sauvegarde les fichiers existants et installe le paquet.</p><p>Les paramètres et la clé OpenAI chiffrée sont conservés. Les fichiers FDB, CSV, DAT et de configuration existants de l’aide, ainsi que l’Info.rtf d’origine, sont sauvegardés sans être remplacés. Les fichiers de modèles restent intacts. En cas d’échec, le programme tente de restaurer les fichiers déjà remplacés et consigne le résultat. Sauvegardes et rapports : <code>%LOCALAPPDATA%/UGSo/IET2026/updates/&lt;identifiant&gt;/</code>.</p><p>Aucun identifiant de serveur nécessaire. Les sommes de contrôle vérifient l’intégrité ; aucune signature numérique de paquet supplémentaire n’est implémentée. 36 tests isolés couvrent le téléchargement, l’annulation, les chemins, la conservation des données, les fichiers verrouillés et la restauration après une écriture partielle.</p><h3 id="correction-du-programme-de-mise-a-jour-2-1-48" tabindex="-1">Correction du programme de mise à jour 2.1.48 <a class="header-anchor" href="#correction-du-programme-de-mise-a-jour-2-1-48" aria-label="Permalink to &quot;Correction du programme de mise à jour 2.1.48&quot;">​</a></h3><p>Le transfert utilise désormais un handle de processus Windows stable au lieu de lire les modules de l’éditeur en cours de fermeture. Quatre tests supplémentaires couvrent x86/x64, les processus terminés, les identités incorrectes et les délais d’attente. Si l’ancien programme 2.1.37 échoue avant l’installation, extraire d’abord le ZIP 2.1.48 complet dans un nouveau dossier. Sauvegarder ses données et ne pas remplacer les bases et dictionnaires existants par ceux du paquet.</p><p>Le parcours complet de la version publiée 2.1.37 vers 2.1.48 a réussi sur une copie de test sauvegardée : téléchargement GitHub, installation et redémarrage automatique. Les 32 valeurs de configuration précédentes, 17 fichiers de données et de modèles contrôlés et 18 configurations utilisateur existantes ont été conservés. Une clé de test DPAPI synthétique est restée identique et déchiffrable ; l’état initial sans clé a ensuite été rétabli. Aucun appel OpenAI n’a été effectué. Le redémarrage a été confirmé par l’identifiant du processus, les versions, les empreintes et la configuration ; la capture de fenêtre Windows a échoué ensuite. Un nouveau test du dialogue GitHub en lecture seule a bien détecté 2.1.48.</p><h2 id="second-programme-info-trans" tabindex="-1">Second programme : Info_trans <a class="header-anchor" href="#second-programme-info-trans" aria-label="Permalink to &quot;Second programme : Info_trans&quot;">​</a></h2><p>Le paquet contient aussi <code>help/Info_trans.exe</code>. <strong>Aide de référence</strong> dans l’éditeur ouvre ce programme dans la langue choisie. La véritable <code>IET2.FDB</code> et son moteur natif Firebird 2.5.8 ont été récupérés dans l’archive de 2019. Aucune installation séparée d’un serveur Firebird n’est nécessaire.</p><p>La base contient 5 entrées de bâtiments, 2 de marchandises et 2 de mises à jour. Les tables des signaux, matériel roulant, objets de voie et paysage sont vides dans l’original. Sont aussi inclus : 236 entrées d’icônes, 369 termes techniques et 2 428 entrées corrigées dans le <strong>dictionnaire DE/EN/FR</strong>. L&#39;anglais est la référence ; les corrections allemandes confirmées et les traductions françaises sont intégrées. Les fragments ont été réunis et les termes mélangés séparés. Les variantes américaines et britanniques conservent leurs indications. Toutes les questions de vérification du dictionnaire sont résolues. Le fichier DE/EN original et la base source restent inchangés dans le paquet complet.</p><p><img src="'+a+'" alt="Info_trans 2.1.37 avec onglets Lime et base d&#39;origine chargée"></p><p><img src="'+o+'" alt="Dictionnaire trilingue Info_trans avec colonnes allemandes, anglaises et françaises lisibles"></p><p><code>Info_trans</code> est compilé pour x86, comme les DLL natives. Le fournisseur géré FirebirdSql.Data.FirebirdClient 7.5.0.0 a été vérifié avec la vraie base Firebird 2.5.8. Les tests lisent des copies séparées et comparent les sept tables avec l’interface DE/EN/FR. Le paquet contient la base source inchangée.</p><p>Les composants absents ou illisibles sont signalés ; l’import SQL est alors désactivé. Une sauvegarde locale précède tout import SQL manuel disponible. La mise à jour automatique du programme reste désactivée.</p><h2 id="donnees-et-confidentialite" tabindex="-1">Données et confidentialité <a class="header-anchor" href="#donnees-et-confidentialite" aria-label="Permalink to &quot;Données et confidentialité&quot;">​</a></h2><p>Les anciennes inscriptions et bases personnelles ne sont pas importées. Les paramètres sont séparés par utilisateur Windows. La configuration OpenAI et les sauvegardes sont conservées sous <code>%LOCALAPPDATA%/UGSo/IET2026/</code>.</p><p>Windows DPAPI chiffre la clé API pour le compte Windows actuel. Les textes sélectionnés sont envoyés à OpenAI avec <code>store: false</code>. Internet et une facturation API distincte sont nécessaires ; un abonnement ChatGPT ne remplace pas cette facturation.</p><h2 id="mise-a-jour-et-verifications" tabindex="-1">Mise à jour et vérifications <a class="header-anchor" href="#mise-a-jour-et-verifications" aria-label="Permalink to &quot;Mise à jour et vérifications&quot;">​</a></h2><p><strong>Les mises à jour GitHub sont lancées manuellement et leur installation doit être confirmée.</strong> L’ancien serveur n’est pas utilisé. Google, LEO, Linguee et DeepL ne sont plus proposés.</p><p>41 contrôles locaux avec réponses API simulées et les compilations Debug/Release vérifient les erreurs, l’annulation, la restauration, l’export et les interfaces rendues DE/EN/FR. Aucun texte n’est envoyé à OpenAI pendant les tests. Un appel API réel et la qualité des traductions produites restent à vérifier avec son propre compte. Tous les schémas INI possibles ne sont pas pris en charge ; vérifier les données obtenues.</p><p>Le paquet local complet 2.1.37 a été contrôlé par l&#39;utilisateur, qui a confirmé son bon fonctionnement avant publication. Le ZIP contient les deux programmes, le moteur Firebird natif, la base originale et le dictionnaire corrigé. L&#39;intégrité du ZIP et son SHA-256 ont été vérifiés ; les sept tables de la base ont été comparées aux interfaces DE/EN/FR sur des copies séparées. Les captures montrent le nouveau design avec des données neutres, sans paramètres privés.</p>',58)])])}const v=s(l,[["render",d]]);export{h as __pageData,v as default};
